/**
 * Unified error type for Zephyr core library.
 * All FFI boundary errors use this type for cross-platform compatibility.
 */
sealed class AppException: kotlin.Exception() {
    
    class IoException(
        
        val v1: kotlin.String
        ) : AppException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NetworkException(
        
        val v1: kotlin.String
        ) : AppException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class ConfigException(
        
        val v1: kotlin.String
        ) : AppException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class CryptoException(
        
        val v1: kotlin.String
        ) : AppException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Cancelled(
        ) : AppException() {
        override val message
            get() = ""
    }
    
    class ParseException(
        
        val v1: kotlin.String
        ) : AppException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class UnknownException(
        
        val v1: kotlin.String
        ) : AppException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AppException> {
        override fun lift(error_buf: RustBuffer.ByValue): AppException = FfiConverterTypeAppError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAppError : FfiConverterRustBuffer<AppException> {
    override fun read(buf: ByteBuffer): AppException {
        

        return when(buf.getInt()) {
            1 -> AppException.IoException(
                FfiConverterString.read(buf),
                )
            2 -> AppException.NetworkException(
                FfiConverterString.read(buf),
                )
            3 -> AppException.ConfigException(
                FfiConverterString.read(buf),
                )
            4 -> AppException.CryptoException(
                FfiConverterString.read(buf),
                )
            5 -> AppException.Cancelled()
            6 -> AppException.ParseException(
                FfiConverterString.read(buf),
                )
            7 -> AppException.UnknownException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AppException): ULong {
        return when(value) {
            is AppException.IoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AppException.NetworkException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AppException.ConfigException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AppException.CryptoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AppException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AppException.ParseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AppException.UnknownException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: AppException, buf: ByteBuffer) {
        when(value) {
